'use strict';
// Parse a compact duration string such as "1h30m", "45s" or "2d4h" into
// milliseconds.
const UNITS = { d: 86400000, h: 3600000, m: 60000, s: 1000 };
// Anchored and with each unit optional but in largest-first order, so the
// grammar itself rejects stray characters, repeated units and out-of-order
// units; the empty match is rejected separately below.
const PATTERN = /^(?:\d+d)?(?:\d+h)?(?:\d+m)?(?:\d+s)?$/;

function parseDuration(input) {
  const text = String(input);
  if (text === '' || !PATTERN.test(text)) {
    throw new RangeError(`Invalid duration: ${JSON.stringify(input)}`);
  }
  let total = 0;
  for (const [, amount, unit] of text.matchAll(/(\d+)([dhms])/g)) {
    total += Number(amount) * UNITS[unit];
  }
  return total;
}

function formatDuration(ms) {
  const parts = [];
  for (const [unit, size] of Object.entries(UNITS)) {
    const n = Math.floor(ms / size);
    if (n > 0) parts.push(`${n}${unit}`);
    ms -= n * size;
  }
  return parts.length > 0 ? parts.join('') : '0s';
}

module.exports = { parseDuration, formatDuration };
